240: // VerifyTask runs the task verification command inside the isolated workspace.
241: func VerifyTask(record *RunRecord, task Task, timeout time.Duration) error {
242: 	if task.VerifyCommand == "" || record.WorkDir == "" {
243: 		return nil
244: 	}
245: 	if timeout <= 0 {
246: 		timeout = 2 * time.Minute
247: 	}
248: 	ctx, cancel := context.WithTimeout(context.Background(), timeout)
249: 	defer cancel()
250: 	parts := strings.Fields(task.VerifyCommand)
251: 	if len(parts) == 0 {
252: 		return nil
253: 	}
254: 	cmd := exec.CommandContext(ctx, parts[0], parts[1:]...)
255: 	cmd.Dir = record.WorkDir
256: 	output, err := cmd.CombinedOutput()
257: 	record.VerifyOutput = string(output)
258: 	if exitError, ok := err.(*exec.ExitError); ok {
259: 		record.VerifyExitCode = exitError.ExitCode()
260: 	} else if err != nil {
261: 		record.VerifyExitCode = -1
262: 	}
263: 	record.VerifyPassed = err == nil
264: 	return nil
265: }
