460: // WriteSummaries writes RESULTS.json and RESULTS.csv from all records in a directory.
461: func WriteSummaries(outputDir string) error {
462: 	entries, err := os.ReadDir(outputDir)
463: 	if err != nil {
464: 		return err
465: 	}
466: 	records := make([]RunRecord, 0)
467: 	for _, entry := range entries {
468: 		if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".json") {
469: 			continue
470: 		}
471: 		if strings.HasSuffix(entry.Name(), ".events.jsonl") {
472: 			continue
473: 		}
474: 		data, err := os.ReadFile(filepath.Join(outputDir, entry.Name()))
475: 		if err != nil {
476: 			continue
477: 		}
478: 		var record RunRecord
479: 		if json.Unmarshal(data, &record) == nil && record.ID != "" {
480: 			records = append(records, record)
481: 		}
482: 	}
483: 	sort.Slice(records, func(i, j int) bool { return records[i].ID < records[j].ID })
484: 
485: 	encoded, err := json.MarshalIndent(records, "", "  ")
486: 	if err != nil {
487: 		return err
488: 	}
489: 	if err := os.WriteFile(filepath.Join(outputDir, "RESULTS.json"), append(encoded, '\n'), 0o644); err != nil {
490: 		return err
491: 	}
