498: 	writer := csv.NewWriter(file)
499: 	header := []string{"id", "taskId", "category", "model", "format", "condition", "success", "verifyPassed", "input", "output", "reasoning", "cacheRead", "cacheWrite", "cost", "durationMs", "toolCalls", "eventCount", "checked", "followed", "violated", "compliancePct"}
500: 	if err := writer.Write(header); err != nil {
501: 		return err
502: 	}
503: 	for _, record := range records {
504: 		row := []string{
505: 			record.ID, record.TaskID, record.Category, record.Model, record.Format, record.Condition,
506: 			fmt.Sprintf("%t", record.Success), fmt.Sprintf("%t", record.VerifyPassed),
507: 			fmt.Sprintf("%d", record.Tokens.Input), fmt.Sprintf("%d", record.Tokens.Output),
508: 			fmt.Sprintf("%d", record.Tokens.Reasoning), fmt.Sprintf("%d", record.Tokens.CacheRead),
509: 			fmt.Sprintf("%d", record.Tokens.CacheWrite), fmt.Sprintf("%.6f", record.Cost),
510: 			fmt.Sprintf("%d", record.DurationMS), fmt.Sprintf("%d", record.ToolCalls),
511: 			fmt.Sprintf("%d", record.EventCount),
512: 			fmt.Sprintf("%d", record.Compliance.Checked), fmt.Sprintf("%d", record.Compliance.Followed),
513: 			strings.Join(record.Compliance.Violated, ";"), fmt.Sprintf("%.2f", record.Compliance.Pct),
514: 		}
515: 		if err := writer.Write(row); err != nil {
516: 			return err
517: 		}
518: 	}
519: 	writer.Flush()
520: 	return writer.Error()
521: }

