117: // LoadCatalog reads a task catalogue from disk.
118: func LoadCatalog(path string) (Catalog, error) {
119: 	data, err := os.ReadFile(path)
120: 	if err != nil {
121: 		return Catalog{}, err
122: 	}
123: 	var catalog Catalog
124: 	if err := json.Unmarshal(data, &catalog); err != nil {
125: 		return Catalog{}, err
126: 	}
127: 	return catalog, nil
128: }
