130: // WriteCatalog writes a task catalogue to disk.
131: func WriteCatalog(path string, catalog Catalog) error {
132: 	data, err := json.MarshalIndent(catalog, "", "  ")
133: 	if err != nil {
134: 		return err
135: 	}
136: 	return os.WriteFile(path, append(data, '\n'), 0o644)
137: }
