139: // InstructionPayload builds the instruction context for a format and delimiter mode.
140: func InstructionPayload(format string, delimiters bool) (string, error) {
141: 	source, err := os.ReadFile("AIL_RULES/project-rules.ail")
142: 	if err != nil {
143: 		return "", err
144: 	}
145: 	parsed := parser.Parse(string(source), "project-rules.ail")
146: 	ir := interpreter.Interpret(parsed).IR
147: 
148: 	if strings.EqualFold(format, "markdown") {
149: 		baseline, err := os.ReadFile("MARKDOWN_BASELINE/project-rules.md")
150: 		if err != nil {
151: 			return "", err
152: 		}
153: 		if !delimiters {
154: 			return string(baseline), nil
155: 		}
156: 		return renderer.InterpretationInstruction() + "\n\n" + renderer.BeginMarker() + "\n\n" +
157: 			string(baseline) + "\n" + renderer.EndMarker() + "\n", nil
158: 	}
159: 
160: 	include := delimiters
161: 	result := renderer.Render(ir, core.RenderOptions{
162: 		Host:              core.HostOpenCode,
163: 		Mode:              core.ModeInline,
164: 		IncludeDelimiters: &include,
165: 	})
166: 	return result.Text, nil
167: }
