176: type finishPart struct {
177: 	Cost   float64 `json:"cost"`
178: 	Tokens struct {
179: 		Input  int `json:"input"`
180: 		Output int `json:"output"`
181: 		Reasoning int `json:"reasoning"`
182: 		Cache struct {
