189: func parseEvents(raw []byte) (text string, tokens Tokens, cost float64, sessionID string, toolCalls, eventCount int) {
190: 	scanner := bufio.NewScanner(bytes.NewReader(raw))
191: 	scanner.Buffer(make([]byte, 1024*1024), 16*1024*1024)
192: 	var builder strings.Builder
193: 	for scanner.Scan() {
194: 		line := bytes.TrimSpace(scanner.Bytes())
195: 		if len(line) == 0 {
196: 			continue
197: 		}
198: 		var item event
199: 		if err := json.Unmarshal(line, &item); err != nil {
200: 			continue
201: 		}
202: 		eventCount++
203: 		if item.SessionID != "" {
204: 			sessionID = item.SessionID
205: 		}
206: 		var part map[string]json.RawMessage
207: 		if err := json.Unmarshal(item.Part, &part); err != nil {
208: 			continue
209: 		}
210: 		if typeRaw, ok := part["type"]; ok {
211: 			var partType string
212: 			_ = json.Unmarshal(typeRaw, &partType)
213: 			if strings.HasPrefix(partType, "tool") {
214: 				toolCalls++
215: 			}
216: 		}
217: 		if item.Type == "text" {
218: 			if textRaw, ok := part["text"]; ok {
219: 				var chunk string
220: 				if json.Unmarshal(textRaw, &chunk) == nil {
221: 					builder.WriteString(chunk)
222: 				}
223: 			}
224: 		}
225: 		if item.Type == "step_finish" {
226: 			var finish finishPart
227: 			if json.Unmarshal(item.Part, &finish) == nil {
228: 				cost = finish.Cost
229: 				tokens.Input = finish.Tokens.Input
230: 				tokens.Output = finish.Tokens.Output
231: 				tokens.Reasoning = finish.Tokens.Reasoning
232: 				tokens.CacheRead = finish.Tokens.Cache.Read
233: 				tokens.CacheWrite = finish.Tokens.Cache.Write
234: 			}
235: 		}
236: 	}
237: 	return builder.String(), tokens, cost, sessionID, toolCalls, eventCount
238: }
