297: func workspaceContainsDash(root string) bool {
298: 	found := false
299: 	_ = filepath.WalkDir(root, func(path string, entry os.DirEntry, err error) error {
300: 		if err != nil || entry.IsDir() {
301: 			return nil
302: 		}
303: 		data, err := os.ReadFile(path)
304: 		if err != nil || len(data) > 1<<20 {
305: 			return nil
306: 		}
307: 		if strings.Contains(string(data), "\u2014") {
308: 			found = true
309: 		}
310: 		return nil
311: 	})
312: 	return found
313: }
314: 
315: func workspaceHasLargeFile(root string) bool {
316: 	found := false
317: 	_ = filepath.WalkDir(root, func(path string, entry os.DirEntry, err error) error {
318: 		if err != nil || entry.IsDir() {
319: 			return nil
320: 		}
321: 		data, err := os.ReadFile(path)
322: 		if err != nil || len(data) > 1<<20 {
323: 			return nil
324: 		}
325: 		if strings.Count(string(data), "\n")+1 > 700 {
326: 			found = true
327: 		}
328: 		return nil
329: 	})
330: 	return found
331: }
