333: // prepareWorkspace creates an isolated directory and writes the task baseline into it.
334: func prepareWorkspace(root, id string, task Task) (string, error) {
335: 	dir := filepath.Join(root, id)
336: 	if err := os.MkdirAll(dir, 0o755); err != nil {
337: 		return "", err
338: 	}
339: 	names := make([]string, 0, len(task.Files))
340: 	for name := range task.Files {
341: 		names = append(names, name)
342: 	}
343: 	sort.Strings(names)
344: 	for _, name := range names {
345: 		path := filepath.Join(dir, name)
346: 		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
347: 			return "", err
348: 		}
349: 		if err := os.WriteFile(path, []byte(task.Files[name]), 0o644); err != nil {
350: 			return "", err
351: 		}
352: 	}
353: 	return dir, nil
354: }
