356: // RunOne executes a single task and persists its record. Completed successful runs are skipped.
357: func RunOne(request Request) (RunRecord, error) {
358: 	if err := os.MkdirAll(request.OutputDir, 0o755); err != nil {
359: 		return RunRecord{}, err
360: 	}
361: 	id := fmt.Sprintf("%s__%s__%s__%s", request.Condition, request.Task.ID, sanitize(request.Model.ID), request.Format)
362: 	recordPath := filepath.Join(request.OutputDir, id+".json")
363: 	if existing, err := os.ReadFile(recordPath); err == nil {
364: 		var record RunRecord
365: 		if json.Unmarshal(existing, &record) == nil && record.Success {
366: 			return record, nil
367: 		}
368: 	}
369: 
370: 	workDir, err := prepareWorkspace(request.WorkspaceRoot, id, request.Task)
371: 	if err != nil {
372: 		return RunRecord{}, err
373: 	}
374: 	binary := request.OpenCodeBinary
375: 	if binary == "" {
376: 		binary = "opencode"
377: 	}
378: 	prompt := request.Instruction + "\n\n--- TASK ---\n\n" + request.Task.Prompt
379: 
380: 	timeout := request.Timeout
381: 	if timeout <= 0 {
382: 		timeout = 10 * time.Minute
383: 	}
384: 	ctx, cancel := context.WithTimeout(context.Background(), timeout)
385: 	defer cancel()
386: 
387: 	args := []string{
388: 		"run",
389: 		"--model", request.Model.ID,
390: 		"--format", "json",
391: 		"--auto",
392: 		"--archived",
393: 		"--title", "ail-bench-"+id,
394: 		prompt,
395: 	}
396: 	cmd := exec.CommandContext(ctx, binary, args...)
397: 	cmd.Dir = workDir
398: 	var stdout, stderr bytes.Buffer
399: 	cmd.Stdout = &stdout
400: 	cmd.Stderr = &stderr
401: 
402: 	record := RunRecord{
403: 		ID:         id,
404: 		TaskID:     request.Task.ID,
405: 		Category:   request.Task.Category,
406: 		Model:      request.Model.ID,
407: 		Format:     request.Format,
408: 		Delimiters: request.Delimiters,
409: 		Condition:  request.Condition,
410: 		StartedAt:  time.Now().UTC(),
411: 		WorkDir:    workDir,
412: 	}
413: 	runErr := cmd.Run()
414: 	record.FinishedAt = time.Now().UTC()
415: 	record.DurationMS = record.FinishedAt.Sub(record.StartedAt).Milliseconds()
416: 	if runErr != nil {
417: 		record.Error = runErr.Error()
418: 		if stderr.Len() > 0 {
419: 			record.Error += ": " + stderr.String()
420: 		}
421: 	}
422: 	if exitError, ok := runErr.(*exec.ExitError); ok {
423: 		record.ExitCode = exitError.ExitCode()
424: 	}
425: 
426: 	text, tokens, cost, sessionID, toolCalls, eventCount := parseEvents(stdout.Bytes())
427: 	record.Text = text
428: 	record.Tokens = tokens
429: 	record.Cost = cost
430: 	record.SessionID = sessionID
431: 	record.ToolCalls = toolCalls
432: 	record.EventCount = eventCount
433: 	record.Success = runErr == nil && text != ""
434: 	if err := VerifyTask(&record, request.Task, 0); err != nil {
435: 		record.VerifyOutput = fmt.Sprintf("verification error: %v", err)
436: 	}
437: 	ScoreCompliance(&record, request.Task)
438: 
439: 	rawPath := filepath.Join(request.OutputDir, id+".events.jsonl")
440: 	if err := os.WriteFile(rawPath, stdout.Bytes(), 0o644); err != nil {
441: 		return record, err
442: 	}
443: 	encoded, err := json.MarshalIndent(record, "", "  ")
444: 	if err != nil {
445: 		return record, err
446: 	}
447: 	if err := os.WriteFile(recordPath, append(encoded, '\n'), 0o644); err != nil {
448: 		return record, err
449: 	}
450: 	return record, nil
451: }
452: 
453: func sanitize(value string) string {
454: 	value = strings.ReplaceAll(value, "/", "-")
455: 	value = strings.ReplaceAll(value, ".", "-")
456: 	value = strings.ReplaceAll(value, " ", "-")
457: 	return value
458: }
