460: // WriteSummaries writes RESULTS.json and RESULTS.csv from all records in a directory.
461: func WriteSummaries(outputDir string) error {
462: 	entries, err := os.ReadDir(outputDir)
463: 	if err != nil {
464: 		return err
465: 	}
466: 	records := make([]RunRecord, 0)
467: 	for _, entry := range entries {
468: 		if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".json") {
469: 			continue
470: 		}
471: 		if strings.HasSuffix(entry.Name(), ".events.jsonl") {
472: 			continue
473: 		}
474: 		data, err := os.ReadFile(filepath.Join(outputDir, entry.Name()))
475: 		if err != nil {
476: 			continue
477: 		}
478: 		var record RunRecord
479: 		if json.Unmarshal(data, &record) == nil && record.ID != "" {
480: 			records = append(records, record)
481: 		}
482: 	}
483: 	sort.Slice(records, func(i, j int) bool { return records[i].ID < records[j].ID })
484: 
485: 	encoded, err := json.MarshalIndent(records, "", "  ")
486: 	if err != nil {
487: 		return err
488: 	}
489: 	if err := os.WriteFile(filepath.Join(outputDir, "RESULTS.json"), append(encoded, '\n'), 0o644); err != nil {
490: 		return err
491: 	}
492: 
493: 	file, err := os.Create(filepath.Join(outputDir, "RESULTS.csv"))
494: 	if err != nil {
495: 		return err
496: 	}
497: 	defer file.Close()
498: 	writer := csv.NewWriter(file)
499: 	header := []string{"id", "taskId", "category", "model", "format", "condition", "success", "verifyPassed", "input", "output", "reasoning", "cacheRead", "cacheWrite", "cost", "durationMs", "toolCalls", "eventCount", "checked", "followed", "violated", "compliancePct"}
500: 	if err := writer.Write(header); err != nil {
501: 		return err
502: 	}
503: 	for _, record := range records {
504: 		row := []string{
505: 			record.ID, record.TaskID, record.Category, record.Model, record.Format, record.Condition,
506: 			fmt.Sprintf("%t", record.Success), fmt.Sprintf("%t", record.VerifyPassed),
507: 			fmt.Sprintf("%d", record.Tokens.Input), fmt.Sprintf("%d", record.Tokens.Output),
508: 			fmt.Sprintf("%d", record.Tokens.Reasoning), fmt.Sprintf("%d", record.Tokens.CacheRead),
509: 			fmt.Sprintf("%d", record.Tokens.CacheWrite), fmt.Sprintf("%.6f", record.Cost),
510: 			fmt.Sprintf("%d", record.DurationMS), fmt.Sprintf("%d", record.ToolCalls),
511: 			fmt.Sprintf("%d", record.EventCount),
512: 			fmt.Sprintf("%d", record.Compliance.Checked), fmt.Sprintf("%d", record.Compliance.Followed),
513: 			strings.Join(record.Compliance.Violated, ";"), fmt.Sprintf("%.2f", record.Compliance.Pct),
514: 		}
515: 		if err := writer.Write(row); err != nil {
516: 			return err
517: 		}
518: 	}
519: 	writer.Flush()
520: 	return writer.Error()
521: }
